package dev.joaomendonca.agendapro.dashboard.api;
import dev.joaomendonca.agendapro.appointment.domain.*;import dev.joaomendonca.agendapro.appointment.infrastructure.*;import dev.joaomendonca.agendapro.customer.infrastructure.*;import dev.joaomendonca.agendapro.employee.infrastructure.*;import dev.joaomendonca.agendapro.shared.security.AuthenticatedTenantProvider;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.*;
@RestController @RequestMapping("/api/v1/dashboard") public class DashboardController{private final AppointmentRepository appointments;private final CustomerRepository customers;private final EmployeeRepository employees;private final AuthenticatedTenantProvider tenant;public DashboardController(AppointmentRepository a,CustomerRepository c,EmployeeRepository e,AuthenticatedTenantProvider t){appointments=a;customers=c;employees=e;tenant=t;}@GetMapping public DashboardResponse get(){var tid=tenant.tenantId();var start=LocalDate.now().atStartOfDay();var end=start.plusDays(1);var today=appointments.findAllByTenantIdAndStartsAtBetweenOrderByStartsAt(tid,start,end);var completed=today.stream().filter(a->a.getStatus()==AppointmentStatus.COMPLETED).toList();var next=today.stream().filter(a->a.getStartsAt().isAfter(LocalDateTime.now())&&a.getStatus()!=AppointmentStatus.CANCELLED).findFirst().orElse(null);String customer=null,employee=null;if(next!=null){customer=customers.findByIdAndTenantId(next.getCustomerId(),tid).map(x->x.getName()).orElse(null);employee=employees.findByIdAndTenantId(next.getEmployeeId(),tid).map(x->x.getName()).orElse(null);}return new DashboardResponse(today.size(),completed.size(),customers.findAllByTenantIdOrderByName(tid).size(),employees.findAllByTenantIdOrderByName(tid).stream().filter(x->x.getStatus().name().equals("ACTIVE")).count(),completed.stream().map(a->a.getPrice()).reduce(BigDecimal.ZERO,BigDecimal::add),next==null?null:next.getStartsAt(),customer,employee);}}
